<?php require "../config.php";require_role("student");$page_title="Student Portal";$s=$conn->prepare("SELECT a.*,p.name program FROM applications a JOIN programs p ON p.id=a.program_id WHERE a.email=? ORDER BY a.id DESC");$s->bind_param("s",$_SESSION["user"]["email"]);$s->execute();$apps=$s->get_result();require "../includes/header.php";?><section class="portal-shell pb-5"><div class="container"><div class="side-nav mb-4"><div class="eyebrow">Student portal</div><h3><?=e($_SESSION["user"]["name"])?></h3><a href="/cgua/admissions/apply.php">New application</a><a href="/cgua/auth/logout.php">Logout</a></div><h1 class="section-title">Your adventure starts here.</h1><div class="dashboard-card mt-4"><h4>Your applications</h4><div class="table-wrap mt-3"><table class="table"><tr><th>Program</th><th>Status</th><th>Date</th></tr><?php while($a=$apps->fetch_assoc()):?><tr><td><?=e($a["program"])?></td><td><?=e($a["status"])?></td><td><?=e($a["created_at"])?></td></tr><?php endwhile;?></table></div></div></div></section><?php require "../includes/footer.php";?>